import React, { useState, useEffect } from 'react';
import { 
  Shield, 
  AlertTriangle, 
  Activity, 
  Globe, 
  Lock, 
  Terminal as TerminalIcon 
} from 'lucide-react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, 
  Tooltip, ResponsiveContainer, AreaChart, Area 
} from 'recharts';

const Dashboard = () => {
  // Fake data for the graph (Network Traffic Simulation)
  const data = [
    { time: '10:00', traffic: 400, threats: 24 },
    { time: '11:00', traffic: 300, threats: 13 },
    { time: '12:00', traffic: 900, threats: 98 }, // Peak/Attack simulation
    { time: '13:00', traffic: 500, threats: 39 },
    { time: '14:00', traffic: 700, threats: 48 },
  ];

  const [logs, setLogs] = useState([
    { id: 1, time: '14:20:05', msg: 'Unauthorized login attempt from IP 192.168.1.45', level: 'High' },
    { id: 2, time: '14:21:10', msg: 'SQL Injection signature detected in Header', level: 'Critical' },
    { id: 3, time: '14:22:15', msg: 'Port scan detected on port 8080', level: 'Medium' },
  ]);

  return (
    <div style={{ backgroundColor: '#0d1117', minHeight: '100vh', color: '#c9d1d9', padding: '20px', fontFamily: 'monospace' }}>

      {/* --- HEADER --- */}
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px', borderBottom: '1px solid #30363d', paddingBottom: '10px' }}>
        <h2 style={{ display: 'flex', alignItems: 'center', gap: '10px', color: '#58a6ff' }}>
          <Shield size={32} /> CyberGuard AI <span style={{fontSize: '12px', background: '#238636', color: 'white', padding: '2px 8px', borderRadius: '10px'}}>LIVE</span>
        </h2>
        <div style={{ display: 'flex', gap: '20px' }}>
          <span>System Status: <b style={{color: '#3fb950'}}>SECURE</b></span>
          <span>Region: <b>Kolkata, IN</b></span>
        </div>
      </header>

      {/* --- STAT CARDS --- */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
        <StatCard icon={<Activity color="#58a6ff"/>} title="Network Load" value="42.5 Mbps" />
        <StatCard icon={<AlertTriangle color="#f85149"/>} title="Active Threats" value="03" />
        <StatCard icon={<Globe color="#d2a8ff"/>} title="Global Nodes" value="12" />
        <StatCard icon={<Lock color="#3fb950"/>} title="Encrypted Sessions" value="1,204" />
      </div>

      {/* --- MAIN CONTENT --- */}
      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>

        {/* Graph Section */}
        <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
          <h3 style={{ marginBottom: '20px' }}>Real-time Traffic Analysis</h3>
          <div style={{ height: '300px', width: '100%' }}>
            <ResponsiveContainer>
              <AreaChart data={data}>
                <CartesianGrid strokeDasharray="3 3" stroke="#30363d" />
                <XAxis dataKey="time" stroke="#8b949e" />
                <YAxis stroke="#8b949e" />
                <Tooltip contentStyle={{backgroundColor: '#0d1117', border: '1px solid #30363d'}} />
                <Area type="monotone" dataKey="traffic" stroke="#58a6ff" fill="#58a6ff" fillOpacity={0.1} />
                <Area type="monotone" dataKey="threats" stroke="#f85149" fill="#f85149" fillOpacity={0.1} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Terminal/Logs Section */}
        <div style={{ background: '#010409', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', maxHeight: '400px', overflowY: 'auto' }}>
          <h3 style={{ marginBottom: '15px', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <TerminalIcon size={20} /> Security Logs
          </h3>
          {logs.map(log => (
            <div key={log.id} style={{ fontSize: '12px', padding: '8px 0', borderBottom: '1px solid #21262d' }}>
              <span style={{ color: '#8b949e' }}>[{log.time}]</span> 
              <span style={{ color: log.level === 'Critical' ? '#f85149' : '#e3b341', marginLeft: '10px' }}>
                {log.level}: {log.msg}
              </span>
            </div>
          ))}
        </div>

      </div>
    </div>
  );
};

// Sub-component for Stats
const StatCard = ({ icon, title, value }) => (
  <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', display: 'flex', alignItems: 'center', gap: '15px' }}>
    <div style={{ background: '#0d1117', padding: '10px', borderRadius: '50%' }}>{icon}</div>
    <div>
      <p style={{ margin: 0, fontSize: '14px', color: '#8b949e' }}>{title}</p>
      <h3 style={{ margin: 0, color: '#f0f6fc' }}>{value}</h3>
    </div>
  </div>
);

export default Dashboard;
